"use client";

import React, { useState, useRef } from "react";
import {
  motion,
  useScroll,
  useMotionValueEvent,
  useSpring,
} from "motion/react";
import { Sparkles, Menu, ArrowUpRight } from "lucide-react";
import { cn } from "@/lib/utils";

export interface ScrollDirectionHeaderProps
  extends React.HTMLAttributes<HTMLDivElement> {
  title?: string;
}

export function ScrollDirectionHeader({
  title = "Studio Horizon",
  className,
  ...props
}: ScrollDirectionHeaderProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const [isVisible, setIsVisible] = useState(true);

  const { scrollY, scrollYProgress } = useScroll({
    container: containerRef,
  });

  const scaleX = useSpring(scrollYProgress, {
    stiffness: 100,
    damping: 30,
    restDelta: 0.001,
  });

  useMotionValueEvent(scrollY, "change", (current) => {
    const prev = scrollY.getPrevious() ?? 0;
    const diff = current - prev;
    if (current > 50 && diff > 4) {
      setIsVisible(false);
    } else if (diff < -4 || current < 50) {
      setIsVisible(true);
    }
  });

  return (
    <div
      data-slot="scroll-direction-header"
      className={cn(
        "relative flex flex-col w-full max-w-xl mx-auto h-[480px] overflow-hidden rounded-3xl border border-neutral-200 dark:border-neutral-800 bg-white dark:bg-neutral-950 shadow-2xl select-none",
        className
      )}
      {...props}
    >
      {/* Smart Auto-Hiding Navbar */}
      <motion.header
        initial={{ y: 0 }}
        animate={{ y: isVisible ? 0 : -80 }}
        transition={{ duration: 0.25, ease: "easeInOut" }}
        className="absolute top-0 left-0 right-0 z-20 flex items-center justify-between border-b border-neutral-100 bg-white/85 px-6 py-3.5 backdrop-blur-md dark:border-neutral-800/80 dark:bg-neutral-900/85"
      >
        <div className="flex items-center gap-2">
          <div className="flex h-7 w-7 items-center justify-center rounded-lg bg-pink-500 text-white shadow-xs">
            <Sparkles className="h-4 w-4" />
          </div>
          <span className="text-sm font-bold text-neutral-900 dark:text-neutral-100">
            {title}
          </span>
        </div>

        <div className="flex items-center gap-2">
          <button
            type="button"
            className="flex items-center gap-1 rounded-full bg-neutral-900 px-3.5 py-1.5 text-xs font-semibold text-white shadow-xs dark:bg-neutral-100 dark:text-neutral-900 cursor-pointer"
          >
            <span>Explore</span>
            <ArrowUpRight className="h-3 w-3" />
          </button>
          <button
            type="button"
            className="flex h-8 w-8 items-center justify-center rounded-lg border border-neutral-200 dark:border-neutral-800 text-neutral-600 dark:text-neutral-300"
          >
            <Menu className="h-4 w-4" />
          </button>
        </div>

        {/* Scroll Progress Bar pinned beneath header */}
        <motion.div
          style={{ scaleX }}
          className="absolute bottom-0 left-0 right-0 h-[2px] origin-left bg-gradient-to-r from-pink-500 to-purple-500"
        />
      </motion.header>

      {/* Scrollable Body Content */}
      <div
        ref={containerRef}
        className="h-full overflow-y-auto pt-20 pb-12 px-6 space-y-6"
      >
        <div className="rounded-2xl bg-neutral-50 p-6 dark:bg-neutral-900 border border-neutral-100 dark:border-neutral-800">
          <span className="text-[10px] font-mono font-bold uppercase tracking-widest text-pink-500">
            Smart Scroll Trigger
          </span>
          <h3 className="text-xl font-bold tracking-tight text-neutral-900 dark:text-neutral-100 mt-1">
            Scroll down inside this frame
          </h3>
          <p className="text-xs text-neutral-600 dark:text-neutral-400 mt-2 leading-relaxed">
            The top navigation bar automatically slides up and conceals itself when scrolling downwards to maximize viewable reading space, and returns smoothly the moment upward momentum is detected.
          </p>
        </div>

        {Array.from({ length: 6 }).map((_, i) => (
          <div
            key={i}
            className="p-5 rounded-2xl border border-neutral-100 bg-white dark:border-neutral-800 dark:bg-neutral-900 shadow-xs"
          >
            <div className="h-3 w-28 bg-neutral-200 dark:bg-neutral-700 rounded-full mb-3" />
            <div className="h-2 w-full bg-neutral-100 dark:bg-neutral-800 rounded-full mb-2" />
            <div className="h-2 w-4/5 bg-neutral-100 dark:bg-neutral-800 rounded-full" />
          </div>
        ))}
      </div>
    </div>
  );
}
